package pag.domains.gen;

import java.math.BigInteger;
import org.junit.jupiter.api.*;
import static org.junit.jupiter.api.Assertions.*;

class IntegerConstraintDomainTest {

    @Test
    void testTopBottom() {
        IntegerConstraintDomain domain = new IntegerConstraintDomain();
        IntegerConstraintDomain.State top = domain.top();
        IntegerConstraintDomain.State bottom = domain.bottom();

        assertFalse(domain.isBottom(top));
        assertTrue(domain.isBottom(bottom));
    }

    @Test
    void testEntails() {
        IntegerConstraintDomain domain = new IntegerConstraintDomain();
        IntegerConstraintDomain.State a = new IntegerConstraintDomain.State();
        a.constraints.put("x", IntegerConstraintDomain.Constraint.UNCONSTRAINED);
        a.constraints.put("y", IntegerConstraintDomain.Constraint.equals(BigInteger.valueOf(5)));

        IntegerConstraintDomain.State b = new IntegerConstraintDomain.State();
        b.constraints.put("x", IntegerConstraintDomain.Constraint.UNCONSTRAINED);
        b.constraints.put("y", IntegerConstraintDomain.Constraint.equals(BigInteger.valueOf(5)));

        assertTrue(domain.entails(a, b));

        // a constrains y to 5, b constrains y to 6 -> a does not entail b
        IntegerConstraintDomain.State c = new IntegerConstraintDomain.State();
        c.constraints.put("y", IntegerConstraintDomain.Constraint.equals(BigInteger.valueOf(6)));
        assertFalse(domain.entails(a, c));
    }

    @Test
    void testJoin() {
        IntegerConstraintDomain domain = new IntegerConstraintDomain();
        IntegerConstraintDomain.State a = new IntegerConstraintDomain.State();
        a.constraints.put("x", IntegerConstraintDomain.Constraint.equals(BigInteger.valueOf(5)));

        IntegerConstraintDomain.State b = new IntegerConstraintDomain.State();
        b.constraints.put("x", IntegerConstraintDomain.Constraint.equals(BigInteger.valueOf(10)));

        IntegerConstraintDomain.State join = domain.join(a, b);

        // Different EQUALS constraints join to BOTTOM (contradiction)
        assertTrue(domain.isBottom(join));
    }

    @Test
    void testWiden() {
        IntegerConstraintDomain domain = new IntegerConstraintDomain();
        IntegerConstraintDomain.State a = new IntegerConstraintDomain.State();
        a.constraints.put("x", IntegerConstraintDomain.Constraint.equals(BigInteger.valueOf(5)));

        IntegerConstraintDomain.State b = new IntegerConstraintDomain.State();
        b.constraints.put("x", IntegerConstraintDomain.Constraint.UNCONSTRAINED);

        IntegerConstraintDomain.State widen = domain.widen(a, b);

        // Widen EQUALS to UNCONSTRAINED
        assertEquals(IntegerConstraintDomain.Constraint.UNCONSTRAINED, widen.constraints.get("x"));
    }

    @Test
    void testTransferAssign() {
        IntegerConstraintDomain domain = new IntegerConstraintDomain();
        IntegerConstraintDomain.State post = new IntegerConstraintDomain.State();
        post.constraints.put("x", IntegerConstraintDomain.Constraint.equals(BigInteger.valueOf(5)));

        Step assign = Step.Assign(
            new pag.api.LVal.Local("x", "int"),
            new pag.api.RVal.IntConst(BigInteger.valueOf(5))
        );

        IntegerConstraintDomain.State pre = domain.transfer(assign, post);

        // After assignment, x = 5. Before assignment, x is unconstrained (assignment overwrites)
        // Source is IntConst, so no constraint on source
        assertTrue(pre.constraints.isEmpty() || !pre.constraints.containsKey("x"));
    }

    @Test
    void testTransferAssignVariableSource() {
        IntegerConstraintDomain domain = new IntegerConstraintDomain();
        IntegerConstraintDomain.State post = new IntegerConstraintDomain.State();
        post.constraints.put("x", IntegerConstraintDomain.Constraint.equals(BigInteger.valueOf(5)));

        Step assign = Step.Assign(
            new pag.api.LVal.Local("x", "int"),
            new pag.api.RVal.Binop(
                new pag.api.RVal.IntConst(BigInteger.valueOf(0)),
                pag.api.BinOp.Add,
                new pag.api.RVal.IntConst(BigInteger.valueOf(5))
            )
        );

        IntegerConstraintDomain.State pre = domain.transfer(assign, post);

        // x is unconstrained before assignment
        assertTrue(pre.constraints.isEmpty() || !pre.constraints.containsKey("x"));
    }

    @Test
    void testTransferAssume() {
        IntegerConstraintDomain domain = new IntegerConstraintDomain();
        IntegerConstraintDomain.State post = new IntegerConstraintDomain.State();
        post.constraints.put("x", IntegerConstraintDomain.Constraint.equals(BigInteger.valueOf(5)));

        Step assume = Step.Assume(new pag.api.RVal.IntConst(BigInteger.valueOf(1)));
        IntegerConstraintDomain.State pre = domain.transfer(assume, post);

        // Assume 1: if post constrains x to 5, and 1 is true (non-zero), keep constraint
        assertEquals(IntegerConstraintDomain.Constraint.equals(BigInteger.valueOf(5)), pre.constraints.get("x"));
    }

    @Test
    void testTransferCall() {
        IntegerConstraintDomain domain = new IntegerConstraintDomain();
        IntegerConstraintDomain.State post = new IntegerConstraintDomain.State();
        post.constraints.put("x", IntegerConstraintDomain.Constraint.equals(BigInteger.valueOf(5)));

        Step call = Step.Call(
            Optional.of(new pag.api.LVal.Local("x", "int")),
