    @Test
    void testBottomPropagation() {
        IntegerConstraintDomain domain = new IntegerConstraintDomain();
        IntegerConstraintDomain.State bottom = new IntegerConstraintDomain.State();
        bottom.constraints.put("x", IntegerConstraintDomain.Constraint.BOTTOM);

        Step assign = Step.Assign(
            new pag.api.LVal.Local("y", "int"),
            new pag.api.RVal.IntConst(BigInteger.valueOf(5))
